Item.method_code:
//クライアントから呼ぶ用 最新版を探してプロモートする

Innovator inn = this.getInnovator();
string targetconfigID = this.getProperty("configID", "");
string targetType = this.getProperty("targetType","");
string newState = this.getProperty("newState", "");

//最新取得
Item getTargetItem = inn.newItem(targetType, "get");
getTargetItem.setProperty("config_id", targetconfigID);
getTargetItem.setProperty("is_current", "1");
getTargetItem = getTargetItem.apply();


Item targetItem = inn.newItem(targetType, "get");
targetItem.setID(getTargetItem.getID());
using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Aras PLM")))
{
    targetItem = targetItem.promote(newState, "promoted by direct promote");
}

if(targetItem.isError())
{
    //return inn.newError(targetItem.getErrorString());
    return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
}

return this;
